    stack = []
    current_group = ""

    for char in paren_string:
        if char == "(":
            if current_group:
                stack.append(current_group)
                current_group = ""
            stack.append("(")
        elif char == ")":
            if current_group:
                stack.append(current_group)
                current_group = ""
            temp = ""
            while stack[-1] != "(":
                temp = stack.pop() + temp
            stack.pop()
            current_group = temp
        else:
            current_group += char

    if current_group:
        stack.append(current_group)

    result = [group for group in stack if group]

    return result

